 void render(){stemStatus=null;songRows=null;songSearch=null;if(visual!=null){visual.release();visual=null;}root=column();root.setBackgroundColor(bg);root.setPadding(dp(20),0,dp(20),0);root.setOnApplyWindowInsetsListener((v,insets)->{root.setPadding(dp(20),insets.getSystemWindowInsetTop(),dp(20),insets.getSystemWindowInsetBottom());return insets;});setContentView(root);root.requestApplyInsets();LinearLayout header=row();TextView brand=text("◉ afterglow.",27,accent);brand.setTypeface(Typeface.DEFAULT,Typeface.BOLD);header.addView(brand,new LinearLayout.LayoutParams(0,dp(64),1));Button settings=button("⚙",this::settings);header.addView(settings,new LinearLayout.LayoutParams(dp(52),dp(48)));root.addView(header);
 ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);body=column();body.setPadding(0,dp(12),0,dp(20));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(service==null){body.addView(text("Starting your listening room…",20,Color.WHITE));return;}switch(page){case 0:home();break;case 1:search();break;case 2:studio();break;case 3:equalizer();break;case 4:themes();break;}mini=column();mini.setPadding(dp(12),dp(4),dp(12),0);mini.setBackground(shape(0xff263128,14));LinearLayout controls=row();trackText=text(service.current().title,13,Color.WHITE);trackText.setSingleLine(true);trackText.setEllipsize(android.text.TextUtils.TruncateAt.END);controls.addView(trackText,new LinearLayout.LayoutParams(0,dp(46),1));Button previous=button("⏮",()->service.previous());previous.setContentDescription("Restart or previous track");controls.addView(previous,new LinearLayout.LayoutParams(dp(44),dp(44)));playButton=button(service.playing()?"Ⅱ":"▶",()->{service.toggle();permissionsForPlayback();});LinearLayout.LayoutParams playLayout=new LinearLayout.LayoutParams(dp(48),dp(44));playLayout.setMargins(dp(4),0,dp(6),0);controls.addView(playButton,playLayout);Button next=button("⏭",()->service.next(1));controls.addView(next,new LinearLayout.LayoutParams(dp(44),dp(44)));mini.addView(controls);LinearLayout timeline=row();timeText=text("0:00",10,0xffb9c8bb);timeline.addView(timeText);seek=new SeekBar(this);seek.setMax(1000);seek.setProgressTintList(android.content.res.ColorStateList.valueOf(accent));timeline.addView(seek,new LinearLayout.LayoutParams(0,dp(32),1));seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int n,boolean user){if(user)timeText.setText(stamp((int)(service.duration()*n/1000L)));}public void onStartTrackingTouch(SeekBar b){seeking=true;}public void onStopTrackingTouch(SeekBar b){service.seek((int)(service.duration()*b.getProgress()/1000L));seeking=false;}});mini.addView(timeline);LinearLayout playbackOptions=row();Button repeatButton=button(service.repeatLabel(),()->{});repeatButton.setTag("repeatMode");repeatButton.setOnClickListener(v->{service.cycleRepeat();((Button)v).setText(service.repeatLabel());});addSpacedControl(playbackOptions,repeatButton);Button qButton=button("Queue · "+service.upcoming.size()+" / 10",this::showQueue);qButton.setTag("queueCount");addSpacedControl(playbackOptions,qButton);mini.addView(playbackOptions);downloadText=text("",11,accent);mini.addView(downloadText);Button cancel=button("Cancel audio download",()->startService(new Intent(this,DownloadService.class).setAction("cancel")));cancel.setTag("cancelDownload");cancel.setVisibility(DownloadService.busy?View.VISIBLE:View.GONE);mini.addView(cancel);root.addView(mini);nav=row();String[] labels={"Listen","Search","Studio","EQ","Themes"};for(int i=0;i<5;i++){final int p=i;Button b=button(labels[i],()->{page=p;render();});b.setTextSize(11);b.setSingleLine(true);b.setPadding(0,0,0,0);b.setMinWidth(0);b.setTextColor(page==i?accent:0xff94a394);b.setBackgroundColor(Color.TRANSPARENT);nav.addView(b,new LinearLayout.LayoutParams(0,dp(60),1));}root.addView(nav);}
