 final Map<Track,Button> songButtons=new IdentityHashMap<>();boolean draggingSong=false;LinearLayout songRows,queueRows;TextView songCount;EditText songSearch;String songQuery="",songSnapshot="";AlertDialog queueDialog,deleteDialog;
 void songList(){
  LinearLayout heading=row();heading.addView(text("Your songs",20,Color.WHITE),new LinearLayout.LayoutParams(0,dp(52),1));Button queueButton=button("Up next",this::showQueue);heading.addView(queueButton,new LinearLayout.LayoutParams(dp(110),dp(48)));body.addView(heading);
  library.controls(body);songSearch=new EditText(this);songSearch.setSingleLine();songSearch.setTextColor(Color.WHITE);songSearch.setHintTextColor(0xff95a296);songSearch.setHint("Filter songs by title or artist");songSearch.setContentDescription("Filter songs by title or artist");songSearch.setText(songQuery);body.addView(songSearch);
  body.addView(text("Swipe right to queue  ·  Swipe left to delete",12,0xffb5c2b6));songCount=text("",12,0xff95a296);body.addView(songCount);songRows=column();body.addView(songRows);
  songSearch.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int before,int count){songQuery=s.toString();renderSongs();}public void afterTextChanged(android.text.Editable e){}});
  renderSongs();
 }
 void renderSongs(){
  if(songRows==null||service==null||draggingSong)return;songButtons.clear();songRows.removeAllViews();List<Integer> matches=library.indices();
  songCount.setText(library.label()+" · "+matches.size()+" of "+service.queue.size()+" songs");
  if(matches.isEmpty())songRows.addView(text("No songs match. Try a different title or artist.",14,0xff95a296));
  for(int original:matches){Track t=service.queue.get(original);LinearLayout line=row();Button song=button((t.favorite?"♥ ":"")+t.title+"\n"+t.artist+" · "+service.trackStatus(t),()->{int idx=service.queue.indexOf(t);if(idx>=0)playTrack(idx);});song.setMaxLines(3);song.setEllipsize(android.text.TextUtils.TruncateAt.END);song.setGravity(Gravity.CENTER_VERTICAL|Gravity.LEFT);song.setPadding(dp(10),0,dp(4),0);LinearLayout.LayoutParams card=new LinearLayout.LayoutParams(0,dp(84),1);card.setMargins(0,dp(6),dp(10),dp(6));FrameLayout swipe=new FrameLayout(this);swipe.setClipChildren(true);swipe.setBackground(shape(0xff193d2b,12));TextView hint=text("",13,Color.WHITE);hint.setPadding(dp(14),0,dp(14),0);hint.setGravity(Gravity.CENTER_VERTICAL);hint.setAlpha(0);swipe.addView(hint,new FrameLayout.LayoutParams(-1,-1));swipe.addView(song,new FrameLayout.LayoutParams(-1,-1));line.addView(swipe,card);songButtons.put(t,song);installSwipe(song,t,hint,swipe);Button options=button("⋮",()->songActions(t));options.setContentDescription("Queue options for "+t.title);line.addView(options,new LinearLayout.LayoutParams(dp(44),dp(60)));songRows.addView(line);}
 }
 void songActions(Track t){
  new AlertDialog.Builder(this).setTitle(t.title).setItems(new String[]{"Play now","Play next","Add to queue",t.favorite?"Remove from favourites":"Add to favourites","Add to playlist","Delete song and cached audio"},(d,which)->{
   if(which==0){int idx=service.queue.indexOf(t);if(idx>=0)playTrack(idx);}
   else if(which==1){toast(service.enqueue(t,true)?"Queued to play next":service.error);}
   else if(which==2){toast(service.enqueue(t,false)?"Added to queue":service.error);}
   else if(which==3){service.favorite(t);}
   else if(which==4){library.add(t);}
   else {confirmDelete(t);}
   renderSongs();renderQueueRows();
  }).show();
 }
 void showQueue(){
  QueueSheet sheet=new QueueSheet(this);queueRows=sheet;
  queueDialog=new AlertDialog.Builder(this).setView(sheet).create();
  queueDialog.setOnDismissListener(d->{sheet.cancelDrag();queueRows=null;queueDialog=null;});queueDialog.show();
  Window window=queueDialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setGravity(Gravity.BOTTOM);sheet.setMinimumHeight((int)(getResources().getDisplayMetrics().heightPixels*.70f));window.setLayout(-1,-2);}
 }
 void renderQueueRows(){if(queueRows instanceof QueueSheet&&!draggingQueue)((QueueSheet)queueRows).refresh();}
 void offerResult(String title,String artist,String id){
  new AlertDialog.Builder(this).setTitle(title).setItems(new String[]{"Play now","Play next","Add to queue"},(dialog,which)->{
   Track track=new Track(title,artist,id,"youtube");int idx=service.append(track);
   if(which==0)playTrack(idx);else toast(service.enqueue(track,which==1)?"Queued · preparing in background":service.error);
  }).show();
 }
 void refreshSongStatus(){
  if(draggingSong)return;
  if(page==0)for(Map.Entry<Track,Button> entry:songButtons.entrySet()){Track t=entry.getKey();String label=(t.favorite?"♥ ":"")+t.title+"\n"+t.artist+" · "+service.trackStatus(t);if(!label.contentEquals(entry.getValue().getText()))entry.getValue().setText(label);}
  if(queueRows!=null&&!draggingQueue){StringBuilder snapshot=new StringBuilder(service.current().title).append(service.playing());for(Track t:service.upcoming)snapshot.append(System.identityHashCode(t)).append(t.title);String value=snapshot.toString();if(!value.equals(songSnapshot)){songSnapshot=value;renderQueueRows();}}
 }
 void addSpacedControl(LinearLayout row,Button button){button.setMinWidth(0);button.setPadding(dp(4),0,dp(4),0);button.setSingleLine();button.setTextSize(11);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.setMargins(dp(4),dp(6),dp(4),dp(6));row.addView(button,lp);}
 void confirmDelete(Track t){deleteDialog=new AlertDialog.Builder(this).setTitle("Delete song?").setMessage("Remove “"+t.title+"” from your library and queue and delete its cached audio? Your original local file is kept.").setPositiveButton("Delete",(d,w)->{service.removeTrack(t);renderSongs();renderQueueRows();}).setNegativeButton("Cancel",null).show();}
 void installSwipe(View v,Track t,TextView hint,FrameLayout background){v.setOnTouchListener(new View.OnTouchListener(){float x,y;boolean swiping,threshold;public boolean onTouch(View view,MotionEvent e){float dx=e.getRawX()-x;switch(e.getActionMasked()){
 case MotionEvent.ACTION_DOWN:view.animate().cancel();x=e.getRawX();y=e.getRawY();swiping=false;threshold=false;break;
 case MotionEvent.ACTION_MOVE:if(!swiping&&Math.abs(dx)>dp(16)&&Math.abs(dx)>Math.abs(e.getRawY()-y)*1.5){swiping=true;draggingSong=true;view.getParent().requestDisallowInterceptTouchEvent(true);}if(swiping){float delta=Math.max(-view.getWidth()*.6f,Math.min(view.getWidth()*.6f,dx));view.setTranslationX(delta);hint.setText(dx>0?"+ Queue":"Delete · confirm");hint.setGravity(Gravity.CENTER_VERTICAL|(dx>0?Gravity.LEFT:Gravity.RIGHT));hint.setAlpha(Math.min(1,Math.abs(dx)/dp(72)));background.setBackground(shape(dx>0?0xff195236:0xff6b2630,12));boolean ready=Math.abs(dx)>=dp(72);if(ready&&!threshold)view.performHapticFeedback(HapticFeedbackConstants.CLOCK_TICK);threshold=ready;}break;
 case MotionEvent.ACTION_UP:if(swiping){final boolean act=Math.abs(dx)>=dp(72),right=dx>0;view.setPressed(false);view.animate().translationX(0).setDuration(180).setInterpolator(new android.view.animation.DecelerateInterpolator()).withEndAction(()->{hint.setAlpha(0);draggingSong=false;if(act){if(right)toast(service.enqueue(t,false)?"Added to queue":service.error);else confirmDelete(t);}refreshSongStatus();}).start();return true;}break;
 case MotionEvent.ACTION_CANCEL:view.animate().translationX(0).setDuration(180).withEndAction(()->{hint.setAlpha(0);draggingSong=false;}).start();swiping=false;break;
 }return swiping;}});}
 TextView stemStatus;

 void studio(){heading("AI ON YOUR COMPUTER","Stem studio.");body.addView(text("Separate a track into vocals, drums, bass and other instruments. Audio is sent to your configured server; your computer does the AI processing.",14,0xffb5c2b6));body.addView(text("Selected: "+service.current().title,18,Color.WHITE));stemStatus=text(StemService.status,14,accent);body.addView(stemStatus);addButton(body,"Server settings",this::serverSettings);addButton(body,"Test server connection",()->startForegroundService(new Intent(this,StemService.class).setAction("test")));addButton(body,"Separate selected track",()->{if(service.queue.isEmpty()){toast("Select a song first");return;}Track t=service.current();if(!"local".equals(t.kind)&&AudioCache.find(this,t.uri)==null){toast("Play this track once to cache it before separating");return;}startForegroundService(new Intent(this,StemService.class).setAction("separate").putExtra("uri",t.uri).putExtra("title",t.title));});addButton(body,"Cancel stem preparation",()->startService(new Intent(this,StemService.class).setAction("cancel")));addButton(body,"Export four stems as WAV ZIP",()->{if(!StemService.output(this).isFile()){toast("Prepare stems first");return;}startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"Afterglow-stems.zip"),30);});body.addView(text("Keep your computer's server running and USB connected for this setup. One track at a time, up to 10 minutes. Keep 1 GB free for upload and export files. EQ controls have their own tab.",12,0xff95a296));}
 void serverSettings(){LinearLayout content=column();content.setPadding(dp(20),dp(8),dp(20),dp(8));content.addView(text("Server address",14,Color.WHITE));EditText address=new EditText(this);address.setSingleLine();address.setText(ServerSettings.url(this));content.addView(address);content.addView(text("Server token · saved encrypted",14,Color.WHITE));EditText token=new EditText(this);token.setSingleLine();token.setInputType(129);token.setText(ServerSettings.token(this));content.addView(token);content.addView(text("USB setup: http://127.0.0.1:8765. Other servers require HTTPS. Selected audio is uploaded to this address only when you start separation.",12,0xff95a296));new AlertDialog.Builder(this).setTitle("Stem server").setView(content).setPositiveButton("Save",(d,w)->{try{ServerSettings.save(this,address.getText().toString(),token.getText().toString());toast("Server settings saved");}catch(Exception e){toast(e.getMessage());}}).setNegativeButton("Cancel",null).show();}

 void permissionsForPlayback(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},12);}
 void playTrack(int idx){service.setSearchKey(apiKey);service.play(idx);permissionsForPlayback();}
 void pick(int request,String type,boolean multiple){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(type).addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,multiple).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,request);}
 String name(Uri u){try(Cursor c=getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception ignored){}return "Local track";}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||service==null)return;if(request==30&&data.getData()!=null){final Uri output=data.getData();executor.execute(()->{try(InputStream in=new FileInputStream(StemService.output(this));OutputStream out=getContentResolver().openOutputStream(output)){byte[] buffer=new byte[65536];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);runOnUiThread(()->toast("Stems exported"));}catch(Exception e){runOnUiThread(()->toast("Export failed. Choose another destination."));}});return;}if(request==10){int start=service.queue.size();ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());for(Uri uri:uris){try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}service.queue.add(new Track(name(uri).replaceFirst("\\.[^.]+$",""),"Local music",uri.toString(),"local"));}service.queueChanged();render();if(service.queue.size()>start)playTrack(start);}else if(request==11&&data.getData()!=null){Uri uri=data.getData();executor.execute(()->{try(InputStream in=getContentResolver().openInputStream(uri)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>1048576)throw new IOException("Playlist must be smaller than 1 MB");}List<String[]> rows=PlaylistParser.parse(out.toString("UTF-8"),name(uri).toLowerCase().endsWith(".csv"));int title=0,artist=-1;boolean header=false;if(!rows.isEmpty()){String[] first=rows.get(0);for(int i=0;i<first.length;i++){String v=first[i].toLowerCase();if(Arrays.asList("title","song","track","song title").contains(v)){title=i;header=true;}if(v.equals("artist"))artist=i;}}if(header)rows.remove(0);ArrayList<Track> imported=new ArrayList<>();for(String[] row:rows.subList(0,Math.min(500,rows.size()))){if(title<row.length&&!row[title].isEmpty()){String id=videoId(row[title]);imported.add(new Track(row[title],artist>=0&&artist<row.length?row[artist]:"",id==null?"":id,id==null?"query":"youtube"));}}runOnUiThread(()->{int added=service.importUnique(imported);page=0;render();toast(added+" imported · "+(imported.size()-added)+" duplicates skipped");});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}});}}
 interface Results{void accept(JSONArray items);}void lookup(String q,int max,Results callback){String key=apiKey;executor.execute(()->{try{URL url=new URL("https://www.googleapis.com/youtube/v3/search?part=snippet&type=video&videoEmbeddable=true&maxResults="+max+"&q="+URLEncoder.encode(q,"UTF-8")+"&key="+URLEncoder.encode(key,"UTF-8"));HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(15000);try{int code=c.getResponseCode();InputStream input=code==200?c.getInputStream():c.getErrorStream();if(input==null)throw new IOException("Search unavailable ("+code+")");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=input.read(b))!=-1)out.write(b,0,n);input.close();JSONObject json=new JSONObject(out.toString("UTF-8"));if(code!=200)throw new IOException(json.optJSONObject("error")!=null?json.getJSONObject("error").optString("message"):"Search unavailable");JSONArray items=json.getJSONArray("items");runOnUiThread(()->{if(!isFinishing())callback.accept(items);});}finally{c.disconnect();}}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}});}
 static String videoId(String text){try{Uri u=Uri.parse(text);String h=u.getHost(),id=null;if("youtu.be".equals(h))id=u.getLastPathSegment();else if(Arrays.asList("www.youtube.com","youtube.com","m.youtube.com").contains(h)){id=u.getQueryParameter("v");if(id==null)id=u.getLastPathSegment();}return id!=null&&id.matches("[A-Za-z0-9_-]{11}")?id:null;}catch(Exception e){return null;}}
 void search(){heading("FIND YOUR NEXT REPEAT","Find your\nfrequency.");EditText q=new EditText(this);q.setTextColor(Color.WHITE);q.setHintTextColor(0xff929b93);q.setTextSize(15);q.setSingleLine();q.setHint("Song, artist, or YouTube link");body.addView(q);LinearLayout results=column();addButton(body,"Search YouTube",()->{String value=q.getText().toString().trim();if(value.isEmpty())return;String id=videoId(value);if(id!=null){offerResult("YouTube track","YouTube",id);return;}if(apiKey.isEmpty()){settings();toast("Add a YouTube Data API key for title search");return;}results.removeAllViews();results.addView(text("Searching…",14,accent));lookup(value,12,items->{results.removeAllViews();if(items.length()==0)results.addView(text("No matches. Try another title.",14,Color.WHITE));for(int i=0;i<items.length();i++)try{JSONObject item=items.getJSONObject(i),snippet=item.getJSONObject("snippet");String title=android.text.Html.fromHtml(snippet.getString("title"),0).toString(),artist=snippet.getString("channelTitle"),video=item.getJSONObject("id").getString("videoId");addButton(results,title+" · "+artist,()->{offerResult(title,artist,video);});}catch(Exception ignored){}});});body.addView(text("Select a result to play now, play next, or add to your queue. Upcoming audio downloads in the background. Search needs an API key; pasted links do not. Only download tracks you have permission to save.",13,0xff95a296));body.addView(results);}
 interface NumberChange{void set(float n);}void slider(LinearLayout host,String title,int min,int max,int initial,NumberChange change){TextView label=text(title+": "+initial,14,Color.WHITE);host.addView(label);SeekBar s=new SeekBar(this);s.setMax(max-min);s.setProgress(initial-min);s.setProgressTintList(android.content.res.ColorStateList.valueOf(accent));s.setThumbTintList(android.content.res.ColorStateList.valueOf(accent));host.addView(s,new LinearLayout.LayoutParams(-1,dp(40)));s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean user){label.setText(title+": "+(p+min));if(user)change.set(p+min);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});}
 void equalizer(){heading("MAKE IT SOUND LIKE YOU","Your pocket\nsound studio.");body.addView(text(service.dspStatus,13,accent));slider(body,"Volume boost · dB",0,12,(int)service.boost,n->{service.boost=n;service.applyEQ();});body.addView(text("Boost quiet tracks up to +12 dB. Limiting stays active while boost is on.",12,0xff95a296));Switch enable=new Switch(this);enable.setText("10-band equalizer");enable.setTextColor(Color.WHITE);enable.setChecked(service.eqEnabled);enable.setOnCheckedChangeListener((v,on)->{service.eqEnabled=on;service.applyEQ();});body.addView(enable);String[] names={"Flat","Bass boost","Vocal","Electronic","My preset"};Spinner presets=new Spinner(this);presets.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));body.addView(presets);addButton(body,"Apply preset",()->{int p=presets.getSelectedItemPosition();float[][] values={new float[10],{6,5,4,2,0,0,0,0,0,0},{-3,-2,-1,1,3,4,3,1,0,-1},{4,3,0,-2,-1,1,0,2,3,4}};for(int i=0;i<10;i++)service.gains[i]=p==4?prefs.getFloat("custom"+i,0):values[p][i];service.applyEQ();render();});String[] bands={"31 Hz","62 Hz","125 Hz","250 Hz","500 Hz","1 kHz","2 kHz","4 kHz","8 kHz","16 kHz"};for(int i=0;i<10;i++){final int b=i;slider(body,bands[i]+" · dB",-12,12,(int)service.gains[i],n->{service.gains[b]=n;service.applyEQ();});}slider(body,"Preamp · dB",-18,6,(int)service.preamp,n->{service.preamp=n;service.applyEQ();});slider(body,"Balance · left / right",-100,100,(int)(service.balance*100),n->{service.balance=n/100;service.applyEQ();});Switch limiter=new Switch(this);limiter.setText("Peak limiter");limiter.setTextColor(Color.WHITE);limiter.setChecked(service.limit);limiter.setOnCheckedChangeListener((v,on)->{service.limit=on;service.applyEQ();});body.addView(limiter);addButton(body,"Save as My preset",()->{SharedPreferences.Editor e=prefs.edit();for(int i=0;i<10;i++)e.putFloat("custom"+i,service.gains[i]);e.apply();toast("Custom preset saved");});body.addView(text("Keep preamp below 0 dB when boosting bands. Processing applies to local and cached audio.",12,0xff95a296));}
 void themes(){heading("CHANGE THE ATMOSPHERE","Different mood.\nSame you.");String[] names={"Afterglow","Spotify","Cyberpunk","Arctic"};int[] colors={0xffa9ef75,0xff1ed760,0xfff5e642,0xff80d7ef},backs={0xff101311,0xff121212,0xff100e20,0xff101d26};for(int i=0;i<names.length;i++){final int n=i;Button b=button("◉  "+names[i],()->{accent=colors[n];bg=backs[n];saveTheme();});b.setTextColor(colors[i]);LinearLayout.LayoutParams themeLayout=new LinearLayout.LayoutParams(-1,dp(70));themeLayout.setMargins(0,dp(6),0,dp(6));body.addView(b,themeLayout);}EditText custom=new EditText(this);custom.setSingleLine();custom.setText(String.format("#%06X",accent&0xffffff));custom.setTextColor(Color.WHITE);custom.setHint("#RRGGBB");body.addView(custom);addButton(body,"Use custom accent",()->{try{String v=custom.getText().toString();if(!v.matches("#[a-fA-F0-9]{6}"))throw new Exception();accent=Color.parseColor(v);saveTheme();}catch(Exception e){toast("Enter a six-digit color such as #A9EF75");}});}
 void saveTheme(){prefs.edit().putInt("accent",accent).putInt("bg",bg).apply();getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);render();}
 void settings(){LinearLayout content=column();content.setPadding(dp(24),dp(8),dp(24),dp(8));content.addView(text("No account needed. Music stays on your phone.",14,Color.WHITE));content.addView(text("YouTube Data API key · saved securely",13,0xffb5c2b6));EditText key=new EditText(this);key.setInputType(129);key.setText(apiKey);key.setSingleLine();content.addView(key);content.addView(text("Enable YouTube Data API v3. The key is encrypted on this phone and kept until you delete it. It is sent only to Google for searches. Links work without a key.",12,0xff95a296));addButton(content,"Delete saved API key",()->new AlertDialog.Builder(this).setTitle("Delete API key?").setPositiveButton("Delete",(d,w)->{service.setSearchKey("");apiKey="";key.setText("");}).setNegativeButton("Cancel",null).show());addButton(content,"Clear song list",()->new AlertDialog.Builder(this).setTitle("Clear all songs?").setMessage("Stops playback and clears your song list, favourites, playlists and queue. Local files and cached audio are kept; use Clear cached audio separately.").setPositiveButton("Clear list",(d,w)->{service.clearLibrary();render();}).setNegativeButton("Cancel",null).show());content.addView(text("Audio cache · "+(AudioCache.size(this)/1048576)+" MB / 3 GB",14,accent));addButton(content,"Clear cached audio",()->{if(DownloadService.busy){toast("Cancel the current download first");return;}java.io.File active=service!=null?AudioCache.find(this,service.current().uri):null;int removed=AudioCache.clear(this,active);toast(removed+" cached tracks removed. Current and upcoming tracks preserved.");});content.addView(text("Native audio engine: yt-dlp + FFmpeg. Cached files can be removed by Android when storage is low. Only download audio you are authorized to save.",12,0xff95a296));ScrollView settingsScroll=new ScrollView(this);settingsScroll.addView(content);new AlertDialog.Builder(this).setTitle("Afterglow settings").setView(settingsScroll).setPositiveButton("Save",(d,w)->{try{apiKey=key.getText().toString().trim();service.setSearchKey(apiKey);toast("Settings saved");}catch(Exception e){toast(e.getMessage());}}).setNegativeButton("Close",null).show();}
 String stamp(int ms){return String.format(Locale.US,"%d:%02d",ms/60000,ms/1000%60);}final Runnable ticker=new Runnable(){public void run(){if(!visible)return;if(service!=null&&playButton!=null){playButton.setText(service.playing()?"Ⅱ":"▶");trackText.setText(service.current().title);timeText.setText(stamp(service.position())+" / "+stamp(service.duration()));downloadText.setText(DownloadService.status);downloadText.setVisibility(DownloadService.status.isEmpty()?View.GONE:View.VISIBLE);View cancel=mini.findViewWithTag("cancelDownload");if(cancel!=null)cancel.setVisibility(DownloadService.busy?View.VISIBLE:View.GONE);if(!seeking)seek.setProgress(service.duration()>0?(int)(service.position()*1000L/service.duration()):0);if(visual!=null&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)visual.attach(service.audioSession());if(!service.error.isEmpty()&&!service.error.equals(lastError)){lastError=service.error;toast(lastError);}if(service.error.isEmpty())lastError="";if(visual!=null){visual.playing=service.playing();visual.setTrack(service.current());}View repeatControl=mini.findViewWithTag("repeatMode");if(repeatControl instanceof Button&&!service.repeatLabel().contentEquals(((Button)repeatControl).getText()))((Button)repeatControl).setText(service.repeatLabel());View qc=mini.findViewWithTag("queueCount");if(qc instanceof Button)((Button)qc).setText("Queue · "+service.upcoming.size()+" / 10");if(stemStatus!=null)stemStatus.setText(StemService.status);refreshSongStatus();}handler.postDelayed(this,400);}};
 protected void onResume(){super.onResume();visible=true;handler.post(ticker);if(visual!=null)visual.invalidate();}protected void onPause(){visible=false;handler.removeCallbacks(ticker);if(visual!=null)visual.release();super.onPause();}protected void onDestroy(){if(bound)unbindService(connection);executor.shutdownNow();super.onDestroy();}
